export function getJudgmentById(id: string): JudgmentRecord | undefined {
  return judgmentsComprehensiveData.find(j => j._id === id);
}

export function searchJudgments(query: string, courtTier?: string, subject?: string): JudgmentRecord[] {
  let list = judgmentsComprehensiveData;
  const q = (query || "").toLowerCase().trim();

  if (q) {
    list = list.filter(j => 
      j.title.toLowerCase().includes(q) ||
      j.caseNumber.toLowerCase().includes(q) ||
      j.bench.toLowerCase().includes(q) ||
      j.summary.toLowerCase().includes(q) ||
      j.officialSource.toLowerCase().includes(q) ||
      j.courtName.toLowerCase().includes(q)
    );
  }

  if (courtTier && courtTier !== "ALL") {
    list = list.filter(j => {
      if (courtTier === "SUPREME") return j.courtTier === "Supreme Court";
      if (courtTier === "HIGH") return j.courtTier === "High Court";
      if (courtTier === "TRIBUNALS") return j.courtTier === "Tribunal";
      return true;
    });
  }

  if (subject && subject !== "ALL") {
    list = list.filter(j => j.subject.toLowerCase() === subject.toLowerCase());
  }

  return list;
}
